def deep_merge_nodes(nodes):
    merged = {}
    for node in nodes:
        for key, value in node.items():
            if key in merged:
                if isinstance(merged[key], dict) and isinstance(value, dict):
                    merged[key] = deep_merge_nodes([merged[key], value])
                else:
