class InventoryValidator:
    def __init__(self, version, data):
        self.version = version
        self.data = data

    def error(self):
        return "Invalid prior version"

    def validate_as_prior_version(self, prior):
        if not isinstance(prior, InventoryValidator):
            return self.error()
        if prior.version >= self.version:
            return self.error()
        if prior.data!= {key: value for key, value in self.data.items() if key in prior.data and prior.data[key] == value}:
            return self.error()
        return None

