def validate_fixity(self, fixity, manifest_files):
    if not isinstance(fixity, dict):
        self.error("Fixity block must be a dictionary.")
        return

    for file, checksums in fixity.items():
        if not isinstance(checksums, dict):
            self.error(f"Fixity for {file} must be a dictionary of checksums.")
            return

        for algo, checksum in checksums.items():
            if not isinstance(checksum, str):
                self.error(f"Checksum for {file} using {algo} must be a string.")
                return

        if file not in manifest_files:
            self.error(f"File {file} in fixity block is not listed in the manifest.")
            return

    return True

