class VersionValidator:
    def __init__(self, base_dir):
        self.base_dir = base_dir
        self.digest_mismatches = {}

    def validate_version_inventories(self, version_dirs):
        root_inventory_path = os.path.join(self.base_dir, 'inventory.json')
        with open(root_inventory_path, 'r') as file:
            root_inventory = json.load(file)

        for i, version in enumerate(version_dirs, start=1):
            version_dir_path = os.path.join(self.base_dir, version)
            inventory_path = os.path.join(version_dir_path, 'inventory.json')

            if not os.path.exists(inventory_path):
                raise FileNotFoundError(f"Inventory not found for version {i}")

            with open(inventory_path, 'r') as file:
                version_inventory = json.load(file)

            for file_key, file_info in version_inventory.items():
                if file_key in root_inventory:
                    root_digest = root_inventory[file_key]['digest']
                    version_digest = file_info['digest']

                    if root_digest!= version_digest:
                        if file_key not in self.digest_mismatches:
                            self.digest_mismatches[file_key] = []
                        self.digest_mismatches[file_key].append((i, version_digest))

        return self.digest_mismatches

def next_version(version):
    major, minor, patch = map(int, version.split('.'))
    patch += 1
    if patch == 10:
        patch = 0
        minor += 1
        if minor == 10:
            minor = 0
            major += 1
    return f"{major}.{minor}.{patch}"

