class OCFLStorageRoot:
    def __init__(self, base_directory):
        self.base_directory = base_directory
        self.manifest_file = os.path.join(base_directory,'manifest.json')
        self.inventory_file = os.path.join(base_directory, 'inventory.json')

    def initialize(self):
        if os.path.exists(self.base_directory):
            raise FileExistsError("The base directory already exists.")

        os.makedirs(self.base_directory, exist_ok=True)

        manifest = {
            "c": "0.0.1",
            "m": [
                {"type": "http://ocfl.io/spec/core/0.0.1#filesystem", "digest": self.compute_digest(self.base_directory), "roles": ["root"]}
            ]
        }

        inventory = {
            "0": {
                "created": "2023-10-01T00:00:00Z",
                "version": "0.0.1",
                "message": "Initial OCFL storage root creation"
            }
        }

        with open(self.manifest_file, 'w') as f:
            json.dump(manifest, f, indent=2)

        with open(self.inventory_file, 'w') as f:
            json.dump(inventory, f, indent=2)

    def compute_digest(self, directory):
        sha256 = hashlib.sha256()
        for root, _, files in os.walk(directory):
            for file in sorted(files):
                file_path = os.path.join(root, file)
                with open(file_path, 'rb') as f:
                    while chunk := f.read(8192):
                        sha256.update(chunk)
        return sha256.hexdigest()

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    for root in self.roots:
        for obj in root.objects:
            num_objects += 1
            is_valid = True

            if validate_objects:
                if not self.validate_object(obj):
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj.id} is invalid.")

            if check_digests and is_valid:
                if not self.check_object_digest(obj):
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj.id} has a digest mismatch.")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

