import os
def _eval_file(prefix, file_path):
    if not file_path.startswith(prefix) or file_path.endswith('.xml'):
        return None

    file_type = None
    if file_path.endswith('.pdf'):
        file_type = 'pdf'
    else:
        file_type = os.path.splitext(file_path)[-1].lower().strip('.')

    component_id = os.path.basename(file_path).split('.')[0]

    if file_type == 'pdf':
        return {component_id: file_path}
    else:
        return {component_id: file_path, 'ftype': file_type, 'file_path': file_path}

