class ExpressionProcessor:
    def absorb(self, args):
        absorbed = []
        for expr in args:
            if isinstance(expr, tuple) and len(expr) == 2:
                a, b = expr
                if isinstance(a, str) and isinstance(b, str):
                    if a == '0':
                        absorbed.append(b)
                    elif b == '0':
                        absorbed.append(a)
                    elif a == '1' and b == '0':
                        absorbed.append('0')
                    elif a == '0' and b == '1':
                        absorbed.append('0')
                    elif a == b:
                        absorbed.append(a)
                    else:
                        absorbed.append(expr)
                else:
                    absorbed.append(expr)
            else:
                absorbed.append(expr)
        return absorbed

class HookRegistry:
    def __init__(self):
        self._registry = {}

    def on(self, hook):
        def decorator(func):
            if hook not in self._registry:
                self._registry[hook] = []
            self._registry[hook].append(func)
            return func
        return decorator

