class Histogram:
    def __init__(self, min_edge, max_edge, bins):
        self.min_edge = min_edge
        self.max_edge = max_edge
        self.bins = bins
        self.bin_width = (max_edge - min_edge) / bins
        self.histogram = [0] * bins

    def fill(self, coord, weight=1):
        if self.min_edge <= coord < self.max_edge:
            index = int((coord - self.min_edge) / self.bin_width)
            self.histogram[index] += weight

def difference(d1, d2, level=-1):
    result = {}
    for k, v in d1.items():
        if k not in d2:
            result[k] = v
        elif isinstance(v, dict) and isinstance(d2[k], dict):
            nested_diff = difference(v, d2[k], level - 1)
            if nested_diff:
                result[k] = nested_diff
        elif level!= 0:
            if isinstance(v, list) and isinstance(d2[k], list):
                nested_diff = [item for item in v if item not in d2[k]]
                if nested_diff:
                    result[k] = nested_diff
            elif isinstance(v, set) and isinstance(d2[k], set):
                nested_diff = v - d2[k]
                if nested_diff:
                    result[k] = nested_diff
    return result

