import subprocess
def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]

    full_command = commands + args
    stderr_option = subprocess.STDOUT if hide_stderr else subprocess.PIPE

    try:
        process = subprocess.Popen(
            full_command,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            env=env
        )
        output, _ = process.communicate()
        if verbose:
            print(output.decode())
        return process.returncode
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        return -1

def plus_or_dot(pieces):
    closest_tag = pieces[-1]
    if "+" in closest_tag:
        return "."
    return "+"

def render(pieces, style):
    if style == 'uppercase':
        return [piece.upper() for piece in pieces]
    elif style == 'lowercase':
        return [piece.lower() for piece in pieces]
    elif style == 'title':
        return [piece.title() for piece in pieces]
    elif style =='reverse':
        return [piece[::-1] for piece in pieces]
    else:
        return pieces

import sys
def tzname_in_python2(namefunc):
    if sys.version_info[0] < 3:
        def wrapper():
            result = namefunc()
            if isinstance(result, unicode):
                return result.encode('utf-8')
            return result
        return wrapper
    return namefunc

