from zope.interface import Interface, implementer, provider, Invalid, InterfaceClass, providedBy
from inspect import signature, Signature
def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    # Check if iface is an Interface or InterfaceClass
    if not isinstance(iface, (Interface, InterfaceClass)):
        raise Invalid("Invalid interface type")

    # Check if candidate claims to provide the interface
    if not tentative and not providedBy(candidate).isOrExtends(iface):
        errors.append(f"{candidate} does not provide the interface {iface}")

    # Check all methods
    iface_methods = iface.names()
    candidate_methods = dir(candidate)

    for method_name in iface_methods:
        if callable(getattr(iface, method_name, None)):
            if method_name not in candidate_methods:
                errors.append(f"Missing method: {method_name}")
            else:
                iface_method = getattr(iface, method_name)
                candidate_method = getattr(candidate, method_name)

                if not callable(candidate_method):
                    errors.append(f"{method_name} is not callable")
                    continue

                # Check method signatures
                iface_signature = signature(iface_method)
                candidate_signature = signature(candidate_method)

                if iface_signature!= candidate_signature:
                    errors.append(f"Signature mismatch for method {method_name}")

    # Check all attributes
    iface_attrs = [attr for attr in iface.names() if not callable(getattr(iface, attr, None))]
    candidate_attrs = dir(candidate)

    for attr_name in iface_attrs:
        if attr_name not in candidate_attrs:
            errors.append(f"Missing attribute: {attr_name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

from zope.interface import InterfaceClass, Invalid, implementer
from zope.interface.verify import verifyClass
def verifyObject(iface, candidate, tentative=False):
    errors = []

    # Step 1: Check if the candidate claims to provide the interface
    if not tentative and not iface.providedBy(candidate):
        errors.append(f"{candidate} does not claim to provide {iface}")

    # Step 2: Verify that the candidate's class implements the interface
    try:
        verifyClass(iface, type(candidate))
    except Invalid as e:
        errors.extend(str(e).split('\n'))

    # Step 3: Collect all errors
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid('\n'.join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    if not hasattr(candidate, '__dict__'):
        return False
    required_methods = iface.__abstractmethods__
    for method in required_methods:
        if not hasattr(candidate, method):
            return False
        if tentative:
            return True
        if not callable(getattr(candidate, method)):
            return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        meta = type(base)
        if meta is not type:
            metaclasses.add(meta)

    if len(metaclasses) == 1:
        return metaclasses.pop()
    elif len(metaclasses) > 1:
        raise TypeError("Cannot create a consistent method resolution "
                        "order (MRO) for bases %r" % (bases,))
    else:
        return type

def minimalBases(classes):
    all_classes = set()
    subclass_of = set()

    for cls, subs in classes.items():
        all_classes.add(cls)
        subclass_of.update(subs)

    return list(all_classes - subclass_of)

