import threading
def cachedmethod(cache, key=hash, lock=None):
    def decorator(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            cache_key = key((func.__name__, args, frozenset(kwargs.items())))
            if lock:
                with lock:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(self, *args, **kwargs)
                    cache[cache_key] = result
                    return result
            else:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(self, *args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

