class LFU:
    def __init__(self):
        self.key_freq = {}
        self.freq_keys = {}
        self.min_freq = 0

    def popitem(self):
        if not self.key_freq:
            return None

        # Get the keys with the minimum frequency
        keys = self.freq_keys[self.min_freq]
        key = keys.pop(0)

        # If no keys left with the minimum frequency, update min_freq
        if not keys:
            del self.freq_keys[self.min_freq]
            self.min_freq += 1

        # Remove the key from key_freq
        value = self.key_freq.pop(key)
        return key, value

