def round_half_to_even(n):
    integer_part = int(n)
    fractional_part = n - integer_part
    if fractional_part < 0.5:
        return integer_part
    elif fractional_part > 0.5:
        return integer_part + 1
    else:
        return integer_part + (integer_part % 2 == 1)

from datetime import timedelta, timezone

class Time:
    def __init__(self, hour, minute, second, microsecond, tzinfo=None):
        self.hour = hour
        self.minute = minute
        self.second = second
        self.microsecond = microsecond
        self.tzinfo = tzinfo

    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

        total_seconds = ticks // 1_000_000_000
        microseconds = (ticks % 1_000_000_000) * 1000

        td = timedelta(seconds=total_seconds, microseconds=microseconds)
        time_of_day = td if td < timedelta(days=1) else td - timedelta(days=1)

        hour = time_of_day.seconds // 3600
        minute = (time_of_day.seconds % 3600) // 60
        second = time_of_day.seconds % 60

        return cls(hour, minute, second, time_of_day.microseconds, tz)

