            def __init__(self, x, y):
                self.x = x
                self.y = y
    elif size == 3:
        class Point3D:
            def __init__(self, x, y, z):
                self.x = x
                self.y = y
                self.z = z
    elif size == 4:
        class Point4D:
            def __init__(self, x, y, z, w):
                self.x = x
                self.y = y
                self.z = z
                self.w = w

    if size == 2:
