def split(s, platform='this'):
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0
    if platform == 1:
        return re.split(r'(\s+)', s)
    elif platform == 0:
        return re.split(r'(\s+)', s.replace('\\', '\\\\'))

from datetime import timedelta
def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        number, timeunit = frequency.split()
        number = int(number)
        timeunit = timeunit.lower()

        if timeunit == "years":
            return timedelta(days=number * 365)
        elif timeunit == "months":
            return timedelta(days=number * 30)
        elif timeunit == "weeks":
            return timedelta(weeks=number)
        elif timeunit == "days":
            return timedelta(days=number)
        elif timeunit == "hours":
            return timedelta(hours=number)
        elif timeunit == "minutes":
            return timedelta(minutes=number)
        elif timeunit == "seconds":
            return timedelta(seconds=number)
        else:
            raise ValueError("Invalid time unit in frequency")

    except (ValueError, AttributeError):
        raise ValueError("Invalid frequency format")

import socket
def is_local(host):
    local_hosts = ['localhost', '127.0.0.1']
    try:
        host_ip = socket.gethostbyname(host)
        if host_ip == '127.0.0.1':
            return True
        local_ips = socket.gethostbyname_ex(socket.gethostname())[2]
        if host_ip in local_ips:
            return True
        if host in local_hosts:
            return True
    except socket.gaierror:
        pass
    return False

