def get_pattern(pattern, strip=True):
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        pattern = re.escape(pattern)
    return re.compile(pattern)

def is_ipv4(target):
    parts = target.split('.')
    if len(parts)!= 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255 or (num > 0 and str(num)!= part):
            return False
    return True

from typing import Optional, Set
from rdflib import URIRef, Graph, Node
def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()
    nodes = set(graph.subjects())

    for node in nodes:
        if not any(graph.triples((node, prop, None))):
            roots.add(node)

    return roots

