import logging
import json
def load_configurations(config_filenames, overrides=None, resolve_env=True):
    if overrides is None:
        overrides = {}

    config_dict = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config_data = file.read()

            if resolve_env:
                config_data = os.path.expandvars(config_data)

            config = json.loads(config_data)

            # Apply overrides
            for key, value in overrides.items():
                config[key] = value

            config_dict[filename] = config

        except (PermissionError, FileNotFoundError) as e:
            error_records.append(logging.LogRecord(name="", level=logging.ERROR, pathname="", lineno=0, msg=str(e), args=(), exc_info=None))

        except json.JSONDecodeError as e:
            error_records.append(logging.LogRecord(name="", level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=None))

        except Exception as e:
            error_records.append(logging.LogRecord(name="", level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=None))

    return config_dict, error_records

