from typing import Set, Tuple, Callable, Optional
def find_tags(text: str, replacer: Optional[Callable[[str], str]] = None) -> Tuple[Set[str], str]:
    in_code_block = False
    tags = set()
    result = []
    i = 0
    while i < len(text):
        if text[i:i+3] == '```':
            in_code_block = not in_code_block
            result.append(text[i:i+3])
            i += 3
        elif text[i] == '#' and not in_code_block:
            j = i + 1
            while j < len(text) and (text[j].isalnum() or text[j] == '_'):
                j += 1
            tag = text[i+1:j]
            tags.add(tag)
            if replacer:
                replaced = replacer(tag)
                result.append(text[i:j].replace(tag, replaced))
            else:
                result.append(text[i:j])
            i = j
        else:
            result.append(text[i])
            i += 1
    return tags, ''.join(result)

